export interface LegalBlock {
  type: 'heading' | 'p' | 'list'
  level?: number
  text?: string
  items?: string[]
}

export const termsBlocks: LegalBlock[] = [
  { type: 'heading', level: 2, text: `Terms & Conditions` },
  { type: 'p', text: `This Site and related Services are provided by RafikiHub whose trading name is Sio Bahati Holdings Ltd & trading address is in the Republic of Kenya. Registered in the Republic of Kenya, Company Number PVT-ZQUAMRQ.` },
  { type: 'heading', level: 4, text: `Use of RafikiHub` },
  { type: 'heading', level: 4, text: `Definitions` },
  { type: 'heading', level: 4, text: `Services available` },
  { type: 'p', text: `RafikiHub makes certain Services available through the Site. These may be subject to certain eligibility criteria. You will be required to agree further contractual terms before receiving such Services. In the event of any conflict, the Service terms will take precedence.` },
  { type: 'list', items: [`For RafikiHub Marketing Privacy Policy see here`, `For RafikiHub Member Service Terms see here`, `For Agent Service Terms see here`, `For RafikiHub Casting Service Terms see here`, `For Sales and Payment Service Terms see here`, `For Rooms & Studio Booking Service Terms see here`] },
  { type: 'heading', level: 4, text: `Privacy & Personal Data` },
  { type: 'heading', level: 4, text: `Intellectual Property` },
  { type: 'heading', level: 4, text: `Rights granted/rights reserved` },
  { type: 'heading', level: 4, text: `Use of the Site` },
  { type: 'list', items: [`not to use the Content or Services for any unlawful purpose;`, `not to make any use of or interfere with the Site or Services such that the whole or part of the Site is interrupted, damaged, rendered less efficient, or the effectiveness or functionality of the Site is in any way impaired;`, `not to use the Site or Services for the transmission or posting of any viruses or any material which is defamatory, offensive or of an obscene or menacing character, or in such a way as to cause annoyance, inconvenience or needless anxiety;`, `not to use a link to or content from a RafikiHub Member (performer's) online profile on any publicly accessible website or otherwise without their express permission. You also agree to remove any link to or content from a RafikiHub Member (performer's) online profile on request;`, `not to use a link to or content or information from casting details accessed via RafikiHub on any publicly accessible website or otherwise without express permission of the RafikiHub Casting Subscriber or their employer. You also agree to remove any link to or content or information from casting details on request;`, `not to (nor to facilitate any third party to) copy, transmit, distribute, publish, commercially exploit or create derivative works of the Site or Content (and associated ideas and information), or the RafikiHub name or Logo, without prior written permission from RafikiHub;`, `not to use the RafikiHub logo, name, brand or materials to imply or attempt to imply any endorsement or other association of any product or company for any purpose.`] },
  { type: 'heading', level: 4, text: `Scraping or Extraction - Prohibition` },
  { type: 'heading', level: 4, text: `No Warranty` },
  { type: 'heading', level: 4, text: `Liability / Disclaimer` },
  { type: 'heading', level: 4, text: `Availability of the Site` },
  { type: 'heading', level: 4, text: `Links to other sites` },
  { type: 'heading', level: 4, text: `Forwarding enquiries to RafikiHub Members` },
  { type: 'heading', level: 4, text: `Changes to these terms & conditions` },
  { type: 'heading', level: 4, text: `General Terms` },
  { type: 'heading', level: 6, text: `Indemnity` },
  { type: 'heading', level: 6, text: `Entire agreement` },
  { type: 'heading', level: 6, text: `Severability` },
  { type: 'heading', level: 6, text: `No waiver` },
  { type: 'heading', level: 6, text: `Kenyan Law` },
  { type: 'p', text: `RafikiHub is committed to using clear and understandable terminology in all of our documents and correspondence, however if anything within this document is unclear then please contact us.` },
  { type: 'heading', level: 2, text: `Membership Terms & Conditions` },
  { type: 'p', text: `This Site and the related Services are provided by RafikiHub whose trading name is Sio Bahati Holdings Ltd & trading address is in the Republic of Kenya. Registered in The Republic of Kenya, Company Number PVT-ZQUAMRQ.` },
  { type: 'p', text: `For details of how to contact us click here` },
  { type: 'p', text: `By agreeing to these terms and conditions, you are entering into contract with RafikiHub and agreeing to the lawful use of your personal data as necessary for the performance of your contract with us.` },
  { type: 'p', text: `Before agreeing to these terms and conditions please ensure you have read the Site Terms relating to our terms of use for our Site, and the Sales & Payment Terms as these form part of your conditions of membership. In the event of any conflict, these Service terms will take precedence.` },
  { type: 'p', text: `You should print and keep a copy of these terms, the Site Terms and the Sales and Payment terms for your records as at the date of joining or renewing.` },
  { type: 'p', text: `Please also read our Privacy Policy` },
  { type: 'heading', level: 4, text: `Definitions` },
  { type: 'p', text: `These terms and conditions set out the conditions relating to joining RafikiHub as a Member and receiving Member Services.` },
  { type: 'heading', level: 4, text: `RafikiHub Member Services` },
  { type: 'heading', level: 4, text: `Your RafikiHub Profile` },
  { type: 'p', text: `Your profile/entry - showing your professional details including name, contact(s), physical details (including general appearance), skills, credits, notes added to your webpage by you, photograph(s) with photographer credit(s), showreels and voice-clips - can be accessed in the following ways:` },
  { type: 'list', items: [`By you (or representative) passing on access details which may be in the form of a hotlink (this could also include a direct link from your agent or representative's own website) or using it for another method as a means to promoting you.`, `By a RafikiHub Casting Professional or other industry professionals, using the site or digital edition, sending on a link to your profile (for instance a casting director sending a link to the director of a production so that they can assess your suitability for a part.)`, `By RafikiHub Casting Subscribers and their invited team members and clients as part of the RafikiHub Casting tools.`, `Where other formats are offered by RafikiHub at time of joining or renewal.`, `By you or your agent, or a hirer, copying your information or otherwise linking to it or accessing it from RafikiHub approved third party project or workflow management systems.`] },
  { type: 'p', text: `Please Note: As many of our Services are primarily promotional tools personal data included in these public profiles may be accessible by other RafikiHub users and/or the public via wide circulation or redistribution, and via our historical archives. Therefore you should never include any personal data on your profile that you would wish to remain private.` },
  { type: 'heading', level: 4, text: `The RafikiHub Link` },
  { type: 'p', text: `RafikiHub does not have access to the casting briefs prior to them being sent out, and cannot take responsibility for information included in them. RafikiHub does however apprise our RafikiHub Casting Professionals of their responsibilities in line with related legislation. Should you have any concerns regarding the nature of a casting brief sent out to you then please use info@rafikihub.com available on the website or contact our offices immediately to report this.` },
  { type: 'p', text: `Please Note: RafikiHub is not an employment agency. It does not become involved in the casting process and cannot act on your behalf in any work related negotiations; we will only pass on messages from potential employers.` },
  { type: 'p', text: `Also, RafikiHub only provides the functionality of The RafikiHub Link and other services. It is not responsible for the content of the job adverts, including opportunities, or the actions of the advertiser or subsequent employer.` },
  { type: 'heading', level: 4, text: `RafikiHub Casting` },
  { type: 'heading', level: 4, text: `RafikiHub Member Criteria` },
  { type: 'heading', level: 4, text: `Your Professional Name` },
  { type: 'p', text: `Please be aware that acceptance of a name by RafikiHub does not guarantee that the performer's use of the name will not result in trade mark infringement actions, or actions for passing off, or other actions by other parties, and that it is the performer's sole responsibility to deal with any such claim. RafikiHub will not be able to intervene in disputes between performers/agents regarding name registrations on RafikiHub, whether this be in relation to trademarked names or otherwise. In such instances, complainants would need to seek contact with the other party.` },
  { type: 'heading', level: 4, text: `Professional information you supply` },
  { type: 'heading', level: 4, text: `Content and clearances - Uploading photos, video and audio clips` },
  { type: 'p', text: `It is also the responsibility of the RafikiHub Member to ensure they have clearance to list details of productions/projects they have been involved in, or will be involved in, without disclosing confidential information which may cause harm to the hiring company concerned.` },
  { type: 'p', text: `You must not upload material that is unlawful, defamatory, abusive, obscene, discriminatory or otherwise inappropriate.` },
  { type: 'p', text: `RafikiHub reserves the right to suspend or withdraw services from RafikiHub Members who violate our terms and conditions, and not to use or make available any material which it deems inappropriate, or to remove material which it considers to be in breach of these terms and conditions.` },
  { type: 'p', text: `If there is any sort of dispute, RafikiHub will take your material offline until you clear the right to use the material.` },
  { type: 'heading', level: 6, text: `Photographs - further notes` },
  { type: 'p', text: `RafikiHub will always hold an approved main photograph for you. In the event that you wish to replace/substitute your main photo we must approve the new one first. Once the new photo is approved you can then remove the old main photo, or it can be hidden. If you wish to exercise further rights with regards to controlling your data such as the deletion of your photographs, please see our Privacy Policy.` },
  { type: 'heading', level: 6, text: `Showreels and voice-clips - further notes` },
  { type: 'p', text: `If you are linking to an existing clip or recording a clip from scratch especially for your showreel / voice-clips, remember that most 20th century scripts are still subject to copyright, and you should seek permission from the publisher.` },
  { type: 'p', text: `RafikiHub Members may use the RafikiHub logo on their own website as long as: it is a single instance of the RafikiHub logo as a link to our website www.rafikihub.com, it is in the context of a factual reference to the role of RafikiHub, and the logo does not imply RafikiHub’s endorsement of any website or online service.` },
  { type: 'heading', level: 4, text: `Your Professional and Personal contact details` },
  { type: 'heading', level: 6, text: `Professional contact details` },
  { type: 'p', text: `When you have an Agent, enquirers will usually contact you via your Agent. If they call our offices then they will only be given your representative's contact details. However, should a RafikiHub Casting Professional tell us that they have been unable to reach your representative, in these instances we will leave a message for your Agent but also try to contact you directly.` },
  { type: 'p', text: `RafikiHub has a formal registration procedure for Agents and access will only be provided to agents where their professional background can be assessed.` },
  { type: 'p', text: `If you are in a RafikiHub database where you do have the option to list personal contact information, please be aware that this information could be widely circulated or shared, including in the public domain, and therefore you should never list information that you would wish to keep private.` },
  { type: 'p', text: `If you have links to public resources outside of RafikiHub such as personal websites or social media, you do so at your own risk.` },
  { type: 'heading', level: 6, text: `Personal contact details` },
  { type: 'p', text: `It is your responsibility to ensure that we have current valid contact information for you, at all times, so that we can contact you with information about your RafikiHub Membership and in some instances so that you can receive information about casting opportunities from third parties.` },
  { type: 'p', text: `If you have links to public resources outside of RafikiHub such as personal websites or social media, you do so at your own risk.` },
  { type: 'heading', level: 6, text: `Your email address` },
  { type: 'p', text: `Owing to the nature of email and the internet, RafikiHub cannot take responsibility for the successful delivery of email to your chosen email provider. Please ensure that you set up your spam filter / junk mail folder correctly to ensure that emails from RafikiHub (including automated emails) can be received.` },
  { type: 'p', text: `You can update your contact preferences at any time by logging onto our Site. Please see our Privacy Policy for further information.` },
  { type: 'heading', level: 4, text: `Restrictions and responsibilities` },
  { type: 'p', text: `All production information (including individual roles/casting breakdowns) sent by RafikiHub Casting Professionals should be treated as strictly private and confidential and details should not be released to any other parties. Agents or RafikiHub Members will be liable where they, or their employees or clients, cause damage (including financial loss) to a hirer by releasing confidential production details in advance of this information being in the public domain.` },
  { type: 'p', text: `In addition please note the Scraping or Extraction - Prohibition in the Site Terms.` },
  { type: 'p', text: `Notwithstanding the above prohibition, to facilitate RafikiHub Members, Agents and RafikiHub Casting Professionals with their workflow management processes, or other activity, RafikiHub may from time to time provide or authorise the use of certain third party software or applications to facilitate additional off Site access to the materials and Content. Such third party packages or systems are strictly subject to the written approval of RafikiHub. A list of currently authorised third party packages or systems is available to RafikiHub Members/Agents/RafikiHub Casting Professionals by contacting RafikiHub. Please note that RafikiHub does not endorse and is not responsible for any such third party packages or systems. Any use is at your own risk and RafikiHub will not be liable for any loss of information, materials, data or otherwise that may occur due to the use of your materials within them. Please contact us for further information or to discuss the use of other packages or applications.` },
  { type: 'p', text: `Any breach of these terms could cause inconvenience and loss to the sender or provider of information, and loss to RafikiHub. RafikiHub reserves the right to terminate your access to The RafikiHub Link and other relevant services without notice in the event of a breach. It also reserves the right to withdraw or withhold The RafikiHub Link service for individual Agents, RafikiHub Members or generally, where it considers this to be commercially desirable or for any other reason it deems appropriate.` },
  { type: 'p', text: `To ensure quality of service we may withhold access to The RafikiHub Link and services in general from RafikiHub Members whom we consider to lack the relevant credentials or professional experience. We also reserve the right to terminate access where our staff or other persons are subject to abusive, offensive or threatening behavior.` },
  { type: 'heading', level: 4, text: `Joining process` },
  { type: 'p', text: `On becoming a RafikiHub Member, your details will go into our database and be made available on our Site at the earliest opportunity. You will then be sent an automated email (to the email address provided on your application) letting you know that your RafikiHub online profile is now live, and allowing you to review the details. A unique login sent at the same time will give you the ability to make changes to most of your online profile. Should you require changes to your professional contact details then you should contact us immediately to have these noted.` },
  { type: 'p', text: `For YP members details may be provided by a Parent/Guardian (with appropriate documentation).` },
  { type: 'p', text: `It is your responsibility on joining to have checked the professional name you wish to use is available, provide a suitable photograph for your application and all other required details. Failure to do so will cause delays to the upload of your details onto our Site, and could also result in your application being rejected by us if all required details or a suitable photograph have not been supplied within 10 days of your application being submitted.` },
  { type: 'p', text: `If you are an adult Member, or an unrepresented young performer, and you have not received an automated email containing your access details within 10 working days of joining RafikiHub then please contact us immediately.` },
  { type: 'heading', level: 4, text: `Website Access Information` },
  { type: 'p', text: `You are responsible for all activities on your account/profile. You must keep your login information secure and confidential. If you do share the login with your Agent, be sure you authorise and instruct them appropriately.` },
  { type: 'p', text: `Young Performers parent/guardians will generally have access to both View PIN and login information as they can verify the ID of parents/guardians to provide access to Young Performers accounts.` },
  { type: 'p', text: `You can change your View PIN after leaving an Agent, or at any time if you have security concerns (stolen RafikiHub Card or similar) by contacting the RafikiHub offices via info@rafikihub.com` },
  { type: 'heading', level: 4, text: `Agents/Training Establishments` },
  { type: 'heading', level: 4, text: `Additional Services` },
  { type: 'heading', level: 4, text: `Multimedia Services` },
  { type: 'heading', level: 6, text: `Media storage and Premium media upgrades` },
  { type: 'p', text: `Media storage services will be withdrawn upon expiry or withdrawal of an individual's RafikiHub Membership(s). No full or partial refunds will be available in respect of premium media services in these circumstances.` },
  { type: 'p', text: `RafikiHub reserves the right to delete all or some of a Member's media on expiry of their premium media upgrade, expiry of their RafikiHub Membership(s) or for any other reason, including, but not limited to, withdrawal of media upload services for whatever reason.` },
  { type: 'p', text: `RafikiHub does not offer its RafikiHub Members the ability to download or otherwise recover media files in their original quality or format. RafikiHub therefore strongly recommends that RafikiHub Members retain their original media files. Furthermore RafikiHub cannot be held responsible for loss or corruption of data, including accidental or intentional deletion by either party.` },
  { type: 'heading', level: 4, text: `RafikiHub Studio Services` },
  { type: 'heading', level: 6, text: `Sio Bahati Monologues` },
  { type: 'heading', level: 6, text: `Sio Bahati Actor On Tape` },
  { type: 'heading', level: 6, text: `Sio Bahati Showreel Editing` },
  { type: 'heading', level: 4, text: `RafikiHub Membership Fees/Payment` },
  { type: 'p', text: `Your RafikiHub Membership is renewed by way of a membership fee based on your membership and the services included, except in relation to the Additional Services where it is charged in accordance with the Additional Services section above. Brand new RafikiHub members (those who have not been in RafikiHub before) joining RafikiHub may cancel their RafikiHub membership at any time within the trial period and agreeing to these terms and conditions, without incurring any fee or penalty (no payment fee will be cashed or debited for any aspect of your membership during this trial period, your payment will only be taken once your trial period has elapsed). No refund is available on an annual RafikiHub membership after this trial period elapses. The cooling off period - up to 30 days - can only be completed in one block. New RafikiHub Members having completed one cooling off period would not be eligible for another. Confirmation of your application following your trial period amounts to an offer by you to purchase a RafikiHub Membership, and is subject to our acceptance. Your RafikiHub Membership starts on our acceptance of your application. You will be prompted to pay for your membership 1-week prior to your trial period elapsing. Please also see our full Sales & Payment Service Terms which form part of your terms of service.` },
  { type: 'heading', level: 4, text: `Payment by Mobile Money Services – M-Pesa, AirTel Money…` },
  { type: 'p', text: `You can also pay your annual membership fee by using mobile money banking services, such as Mpesa, AirTel Money, still accessible from the online payment platform on rafikihub.com Provided you have a mobile money account set-up with your mobile provider, you can make payment for RafikiHub membership fees by following the mobile banking steps on the payment pages. You will be required to make payment for the membership you require from RafikiHub to the full amount displayed on the membership and payment pages of the Site. You will not be allowed to purchase or use any RafikiHub services without making payment for those services. If, on the expiry of your membership, you wish to rejoin RafikiHub, you would first need to settle in full any unpaid amounts on expired annual membership contracts, together with any interest and debt collection charges RafikiHub may wish to add. RafikiHub reserves the right to remove, for any reason whatsoever, the ability for a member to choose to pay by monthly instalments. It is important that you keep your email address for communications up to date.` },
  { type: 'heading', level: 4, text: `Membership` },
  { type: 'p', text: `We reserve the right to make price changes to future membership fees. This will not affect your current annual membership fees but future fees may increase. We will always notify you of any changes in fees in advance of your membership renewal.` },
  { type: 'heading', level: 4, text: `RafikiHub Membership Cancellation` },
  { type: 'p', text: `RafikiHub reserves the right to refuse or cancel membership for any RafikiHub Member without explanation. In the event that membership is cancelled or refused at will by RafikiHub, a full refund will be given. We additionally reserve the right to terminate RafikiHub Membership temporarily or permanently where our staff or other persons are subject to abusive, offensive or threatening behavior. You will be contacted each year or month (based on your membership plan) to confirm that you wish your RafikiHub Membership to continue. Should you decide to terminate your RafikiHub Membership then your profile will still be available for the duration of time quoted at your last membership renewal. Should your RafikiHub Membership lapse, we may endeavor to offer you another chance to re-join before your details are removed and will retain the necessary amount of personal or professional data in order to meet this purpose. We may also endeavor to contact you with one more opportunity to rejoin the year after your RafikiHub Membership lapses. We do not guarantee to make these follow up offers. If you contact us and ask to cancel with immediate effect we will then remove your online profile (including any multimedia attached) immediately. You would not be eligible for a refund in these circumstances.` },
  { type: 'heading', level: 6, text: `RafikiHub Membership cancellation and personal details` },
  { type: 'p', text: `When a RafikiHub Member cancels their membership we retain their contact details in our internal database in line with our retention policy for reference purposes, for the following reasons:` },
  { type: 'list', items: [`For beneficial professional enquiries (former Agents/Hirers trying to contact you via RafikiHub with outstanding payments, etc.). In which case we may attempt to contact you to pass on a message.`, `Some details are also retained so that when you next rejoin RafikiHub you are recognised as an approved former RafikiHub Member and your online profile can be activated as quickly as possible.`, `To ascertain the previous membership status of those applying for future RafikiHub Membership, in order to administer cooling off periods and similar where required.`] },
  { type: 'heading', level: 4, text: `Deceased Members` },
  { type: 'p', text: `In the event of the death of a member, the estate/members family can inform RafikiHub of this by contacting info@rafikihub.com. The estate/members family may be required to provide a copy (not an original) of the death certificate which will be deleted as soon as it has been reviewed and verified. Once this has been verified, RafikiHub will take appropriate actions in terms of administering the deceased member's profile and account. If the deceased member's RafikiHub membership was paid by card or mobile money, the estate/members family may be entitled to receive a refund of unexpired whole months of the year's membership from the date of death.` },
  { type: 'heading', level: 4, text: `Disclaimers and Liability` },
  { type: 'p', text: `Notwithstanding that appropriate steps have been taken to ensure that the information we publish is accurate, RafikiHub (and those organisations on whose behalf we publish) cannot be held responsible for any errors or omissions, and cannot accept liability for reliance placed on the contents and/or any omissions which may occur. Due to the inherent nature of the internet, and other technology systems we use, errors interruptions and delays may occur in the Service at any time. Accordingly, the Site and Services are provided without any warranties of any kind and we do not accept any liability arising from any inaccuracy or omission in the information or interruption in availability. RafikiHub, whilst using every endeavor to reproduce information punctually on the dates announced, is not to be liable for any delay. RafikiHub asks for full information for those seeking a RafikiHub Casting Subscription, and only allows this to be purchased where we are happy that the RafikiHuib Casting Subscriber can offer our RafikiHub Members valid professional work opportunities. However, RafikiHub cannot take responsibility where false information may have been provided, and this is why we ask our RafikiHub Members never to list personal/sensitive information on their profile. RafikiHub only provides the functionality of The RafikiHub Link and other services. It is not responsible for the content of the job adverts or the actions of the casting professionals or any subsequent employer. Because of the promotional nature of your online profile, RafikiHub cannot control its circulation by those parties mentioned above. We also cannot control disposal or redistribution of our online/printed/digital products. RafikiHub does not endorse or approve any Agents or RafikiHub Casting Professionals (or their employers). RafikiHub Members should make their own enquiries of prospective Agents or hirers and satisfy themselves as to their credentials. RafikiHub does not endorse and is not responsible for any third party packages or systems that help manage information or workflow, even if approved by RafikiHub. RafikiHub will not be liable for any consequences arising from the use of such packages or systems. To the maximum extent permitted by applicable law, we exclude all liability for any indirect, special, consequential or punitive damages, or any loss of income, profits, goodwill, data or contracts arising from or connected in any way to your use of the Services or Site your reliance on the Content, whether in tort (including without limitation negligence), contract or otherwise, even if advised of the possibility of such damages. To the extent there is any liability on us, this is limited at a maximum amount per claim and in aggregate to the annual amount paid by you for the relevant Service. This Section does not in any way limit our liability for death or personal injury caused by our negligence; for fraud or fraudulent misrepresentation; or for any implied terms or other matter for which it would be illegal for us to exclude, or attempt to exclude, our liability.` },
  { type: 'heading', level: 4, text: `Security Concerns` },
  { type: 'p', text: `Should you believe that your RafikiHub online profile is being linked, without your consent, to any other publicly available area, by an individual or organisation, other than your Agent or representative, please inform us via info@rafikihub.com. If you have security concerns at any time we can:` },
  { type: 'list', items: [`Change your RafikiHub View PIN and login (both of these would need to be changed for security reasons), or`, `Change your RafikiHub reference number appearing on your web page URL (this would mean all your data being re-entered into the RafikiHub database, and the automated creation of new View PIN and login).`] },
  { type: 'heading', level: 4, text: `Website Security` },
  { type: 'p', text: `We take all reasonable precautions to keep website interactions secure. We also have strict security procedures regarding the storage and disclosure of information. However, RafikiHub cannot be held liable for any losses caused as a result of unauthorised access to the information provided by you. The security of information transmitted via the internet cannot be guaranteed. Any losses incurred or sustained by users who transmit information by means of email or other internet link shall be borne solely and exclusively by such user and in no event shall any such losses in whole or part be borne by RafikiHub. Security advice note: We recommend that when conducting an online operation you do not use a public or shared computer or a device such as a laptop or mobile phone while you are using public wireless networks. Make sure that nobody can see your confidential details whilst you are typing, logout and close your browser when you have finished. The computer you use to attach to our system should be secure, and include the latest operating system, software and anti-virus updates.` },
  { type: 'heading', level: 4, text: `Status and role of RafikiHub` },
  { type: 'p', text: `RafikiHub is not an employment agency, and RafikiHub never takes commission on work opportunities found for or by its RafikiHub Members. It does not become involved in the casting process and cannot act on your behalf in any work related negotiations; we will only pass on messages from potential employers. RafikiHub does not have access to any arrangements between worker and hirer relating to meeting or working venues, and other terms of employment; therefore RafikiHub Members or their representatives should use due diligence in reviewing their safety arrangements and the terms of any contract supplied by a hirer. RafikiHub will not accept fees for work on behalf of any Member; all payments for work must be arranged between the worker and the hirer, or their official representative.` },
  { type: 'heading', level: 6, text: `EQUAL OPPORTUNITIES` },
  { type: 'p', text: `RafikiHub is not involved in compiling the job adverts which appear on The RafikiHub Link. RafikiHub is committed to equal opportunities for all performers, irrespective of sex, age, race, disability, religion, sexual orientation, marital status or any other criteria not related to skills or abilities. Where sex, age, height and/or appearance have been specified on an advert, the casting director has confirmed that such characteristics are a genuine occupational requirement of the role.` },
  { type: 'heading', level: 6, text: `NATIONAL MINIMUM WAGE` },
  { type: 'p', text: `RafikiHub strongly believes that all commercial productions should pay performers the National Minimum Wage or above. However, we cannot take responsibility for the payment offered by any company, organisation or individual using our casting services. Please see the Kenya Film Commission/Kenya Actors Guild current guidance for full information about the legal framework which covers low pay and no pay work in the entertainment industry, to ensure that you understand your rights and entitlements.` },
  { type: 'heading', level: 4, text: `Research into improved technology and developing new functionality` },
  { type: 'p', text: `We are constantly looking for new ways to change and upgrade our services and the functionality that we can provide to you, including through the use of the latest technology. This may involve partnering with selected and trusted research organisations and technology providers to contribute to their research and innovation projects. Often the most innovative developments come from other industries or fields of research outside of our own, and the outputs of the research may have a broader application beyond the improvements from which we directly benefit. As part of this research and to develop these improvements, our trusted partners may be given access to our systems and data and/or be provided with copies of our data, including Member photos, video and audio clips, and other professional information. You acknowledge this disclosure of your professional information for the above purposes. In all such circumstances our partners' access to and use of this information will be strictly limited to specific research projects that may benefit RafikiHub and our services to you, and will be under secure, confidential, temporary conditions and closed testing environments. Under no circumstances will this information be used for any commercial or live operational activity, other than to develop and test the specific technology and functionality, without your explicit prior consent. Your personal information and contact details will never be disclosed or used in this way.` },
  { type: 'heading', level: 4, text: `General Terms` },
  { type: 'heading', level: 6, text: `Indemnity` },
  { type: 'p', text: `If you breach these terms we may suffer loss. You agree to indemnify us against any and all claims, actions, suits or proceedings, as well as any and all losses, liabilities, damages, costs and expenses (including reasonable legal fees) arising out of any non-compliance by you with these terms and conditions.` },
  { type: 'heading', level: 6, text: `Entire Agreement` },
  { type: 'p', text: `These terms and conditions (as amended from time to time) together with any document expressly referred to in them comprise the entire agreement between you and us.` },
  { type: 'heading', level: 6, text: `Severability` },
  { type: 'p', text: `Each provision of these terms and conditions shall be construed separately, applying and surviving even if for any reason one or other provisions is held to be inapplicable or unenforceable in any circumstances.` },
  { type: 'heading', level: 6, text: `No Waiver` },
  { type: 'p', text: `No waiver by us shall be construed as a waiver of any preceding or succeeding breach of any provision.` },
  { type: 'heading', level: 6, text: `Kenyan Law` },
  { type: 'p', text: `These terms and conditions shall be governed by Kenyan law and you submit to the exclusive jurisdiction of the Kenyan Courts.` },
  { type: 'p', text: `RafikiHub is committed to using clear and understandable terminology in all of our documents and correspondence, however if anything within this document is unclear then please contact us.` },
  { type: 'heading', level: 2, text: `Agent Terms & Conditions` },
  { type: 'p', text: `This Site and the related Services are provided by RafikiHub whose trading name is Sio Bahati Holdings Ltd & trading address is in the Republic of Kenya. Registered in The Republic of Kenya, Company Number PVT-ZQUAMRQ.` },
  { type: 'p', text: `By agreeing to these terms and conditions, you are entering into contract with RafikiHub and agreeing to the lawful use of your personal data as necessary for the performance of your contract with us.` },
  { type: 'p', text: `Before agreeing to these terms and conditions please ensure you have read the Site Terms relating to our terms of use for our Site and our Membership Terms as these form part of your conditions of membership. In the event of any conflict, these Service terms will take precedence.` },
  { type: 'p', text: `You should print and keep a copy of these terms and the Sales and Payment terms for your records as at the date of joining or renewing. Please also read our Privacy Policy.` },
  { type: 'heading', level: 6, text: `Definitions` },
  { type: 'p', text: `- "Agent" means an authorised agent of a performer, who is a Member of RafikiHub. - "Agent Services" means the services made available to Agents as detailed below and on the Site. - "Casting Services" means the services made available to Casting Professionals. - "RafikiHub Casting Professional" means a casting professional who has signed up with RafikiHub as a recipient of the Casting Services. - "Content" means the information and other material or applications available within the Site or relevant Services. - "RafikiHub Member" means a performer/creative who has signed up with RafikiHub as a member of its database and recipient of the Member Services. - "RafikiHub Member Services" means the services that may be made available by RafikiHub to Members as detailed below and on the Site. - "Sales and Payment Terms" means the further specific terms relating to the processing of any payments. - "Site" means the sites located at rafikihub.com - "You" means the user of the Site(s) or the Content or otherwise the Agent. - "We/Us" means RafikiHub. These terms and conditions set out the conditions relating to using RafikiHub as an Agent which includes your actions on behalf of your clients as RafikiHub Members who are receiving RafikiHub Member Services. Please note you must comply with the RafikiHub Member Services Terms in relation to their application to your clients.` },
  { type: 'heading', level: 6, text: `Agent Services` },
  { type: 'p', text: `RafikiHub helps agents to promote their clients to casting opportunities by submitting their clients for castings. The Services are summarised below with further information available on the Site as indicated.` },
  { type: 'heading', level: 4, text: `The RafikiHub Link` },
  { type: 'p', text: `The RafikiHub Link is a system allowing industry professionals who are RafikiHub Casting Professionals to send out casting breakdowns to Agents and RafikiHub Members. As an Agent, your access to RafikiHub will include defined levels of access to The RafikiHub Link.` },
  { type: 'p', text: `RafikiHub does not have access to the casting briefs prior to them being sent out, and cannot take responsibility for information included in them. RafikiHub does however appraise our RafikiHub Casting Professionals of their responsibilities in line with related legislation. Should you have any concerns regarding the nature of a casting brief sent out to you then please contact our offices immediately to report this.` },
  { type: 'heading', level: 4, text: `RafikiHub Casting` },
  { type: 'p', text: `RafikiHub Casting is an end-to-end casting service for the professional casting industry, providing tools and facilities for streamlining the casting process.` },
  { type: 'heading', level: 4, text: `Role as an Agent - authority to act on behalf of clients` },
  { type: 'p', text: `We contract with RafikiHub Members, not Agents. As an Agent, you agree to these terms and conditions relating to Agent Services, but also acknowledge and agree to abide by the RafikiHub Member Services Terms on behalf of any of your clients who are RafikiHub Members. You confirm your understanding of your role as Data Controller, in line with current legislation, in regard to the administration of data in the services you have access to.` },
  { type: 'heading', level: 4, text: `Agent Criteria` },
  { type: 'p', text: `To ensure quality of service we may withhold access to The RafikiHub Link and Agent Services in general from Agents whom we consider to lack the relevant credentials or professional experience. We also reserve the right to terminate access where our staff or other persons are subject to abusive, offensive or threatening behavior.` },
  { type: 'heading', level: 4, text: `Restrictions and responsibilities` },
  { type: 'p', text: `The Content and/or information sent or made available via The RafikiHub Link or otherwise on the Site is the confidential information and copyright of the relevant sender or provider (or of his/her employer). In using The RafikiHub Link, you agree not to forward or copy any part of this information and that you will only use the casting breakdowns, and the information set out in them, for the purposes of suggesting clients for the relevant casting opportunity, by, and only by using the link provided in the system to send proposals back to the relevant RafikiHub Casting Professionals.` },
  { type: 'p', text: `All production information (including individual roles/casting breakdowns) sent by RafikiHub Casting Professionals should be treated as strictly private and confidential and details should not be released to any other parties. Agents will be liable where they, or their employees or clients, cause damage (including financial loss) to a RafikiHub Casting Professional (or their employer) by releasing confidential production details in advance of this information being in the public domain. In addition please note the Scraping or Extraction - Prohibition in the Site Terms.` },
  { type: 'p', text: `Notwithstanding the above prohibition, to facilitate RafikiHub Members, RafikiHub Agents and RafikiHub Casting Professionals with their workflow management processes, or other activity, RafikiHub may from time to time provide or authorise the use of certain third party software or applications to facilitate additional off Site access to the materials and Content. Such third party packages or systems are strictly subject to the written approval of RafikiHub. A list of currently authorised third party packages or systems is available to RafikiHub Members/RafikiHub Agents/RafikiHub Casting Professionals by contacting RafikiHub. Please note that RafikiHub does not endorse and is not responsible for any such third party packages or systems. Any use is at your own risk and RafikiHub will not be liable for any loss of information, materials, data or otherwise that may occur due to the use of your materials within them. Please contact us for further information or to discuss the use of other packages or applications.` },
  { type: 'p', text: `It is the responsibility of Agents to contact RafikiHub and ensure they have suitable consent before moving any RafikiHub Materials and Data into third party systems or software.` },
  { type: 'p', text: `Any breach of these terms could cause inconvenience and loss to the sender or provider of information, and loss to RafikiHub. RafikiHub reserves the right to terminate your access to The RafikiHub Link and other relevant services without notice in the event of a breach. It also reserves the right to withdraw or withhold The RafikiHub Link service for individual Agents or generally, where it considers this to be commercially desirable or for any other reason it deems appropriate.` },
  { type: 'p', text: `RafikiHub does not verify, endorse or approve any Agents. Agents should not present themselves as having any relationship with RafikiHub other than as set out herein.` },
  { type: 'p', text: `RafikiHub Members or their Agents may use the RafikiHub logo on their own website as long as: it is a single instance of the RafikiHub logo as a link to our website www.rafikihub.com, it is in the context of a factual reference to role of RafikiHub, and the logo does not imply RafikiHub’s endorsement of any website or online service; you notify info@rafikihub.com including the full web address of the page(s) where our logo is used.` },
  { type: 'heading', level: 4, text: `Sign Up Process` },
  { type: 'p', text: `RafikiHub has a formal registration procedure for Agents and access will only be provided to agents where their professional background can be assessed. We additionally hold information about agencies, and provide agency services, only if they have clients appearing in RafikiHub (RafikiHub Members) who choose to publish a particular agency as their representative on their RafikiHub profile. You will be informed by an auto-generated email and will then be asked to set up a confidential username and password.` },
  { type: 'p', text: `Please note that administrative rights to RafikiHub agency accounts are held by the Agent concerned (Business Owner) and not by the individual agency employees, and therefore access to any account attached to that Agent (or details of any activities undertaken on an associated agency account) will be given to Agent administrators, 'Main Users' by RafikiHub on request. In the event of any issues or disputes RafikiHub will take instructions only from a Business Owner. Agent employees should additionally be aware that they have no right to gain access, or attempt to gain access, to their RafikiHub agency account once they have left employment with the Agent concerned.` },
  { type: 'p', text: `More information about our services for Agents including The RafikiHub Link and how to enter new clients can be found at http://www.rafikihub.com Please be aware however, that RafikiHub is a professional database and we have strict criteria relating to industry training or experience when vetting RafikiHub Members, which they will need to fulfil.` },
  { type: 'heading', level: 4, text: `RafikiHub Member website access` },
  { type: 'p', text: `On joining RafikiHub, RafikiHub Members will be provided with access information (a username and password). The RafikiHub Link is available to both RafikiHub Members and their Agents for promotional purposes and can be shared with those you wish to view the RafikiHub Member's RafikiHub page. The login is confidential, allowing live changes to the RafikiHub Member's online profile and account administration access, and should never be shared.` },
  { type: 'heading', level: 4, text: `Disclaimers and Liability` },
  { type: 'p', text: `Notwithstanding that appropriate steps have been taken to ensure that the information we publish is accurate, RafikiHub (and those organisations on whose behalf we publish) cannot be held responsible for any errors or omissions, and cannot accept liability for reliance placed on the contents and/or any omissions which may occur.` },
  { type: 'p', text: `Due to the inherent nature of the internet, and other technology systems we use, errors interruptions and delays may occur in the Service at any time. Accordingly, the Site and Services are provided without any warranties of any kind and we do not accept any liability arising from any inaccuracy or omission in the information or interruption in availability.` },
  { type: 'p', text: `RafikiHub does not endorse and is not responsible for any third-party packages or systems that help manage information or workflow, even if approved by RafikiHub. RafikiHub will not be liable for any consequences arising from the use of such packages or systems.` },
  { type: 'p', text: `To the maximum extent permitted by applicable law, we exclude all liability for any indirect, special, consequential or punitive damages, or any loss of income, profits, goodwill, data or contracts arising from or connected in any way to your use of the Services or the Site, whether in tort (including without limitation negligence), contract or otherwise, even if advised of the possibility of such damages. To the extent there is any liability on us, this is limited at a maximum amount per claim and in aggregate to the annual amount paid by you for the relevant Service.` },
  { type: 'p', text: `This Section does not in any way limit our liability for death or personal injury caused by our negligence; for fraud or fraudulent misrepresentation; or for any implied terms or other matter for which it would be illegal for us to exclude, or attempt to exclude, our liability.` },
  { type: 'heading', level: 4, text: `Status and role of RafikiHub` },
  { type: 'p', text: `RafikiHub is not an employment agency, and RafikiHub never takes commission on work opportunities found for or by its RafikiHub Members. It does not become involved in the casting process and cannot act on your behalf in any work related negotiations; we will only pass on messages from potential employers. RafikiHub does not have access to any arrangements between worker and hirer relating to meeting or working venues, and other terms of employment; therefore RafikiHub Members or their representatives should use due diligence in reviewing their safety arrangements and the terms of any contract supplied by a hirer. RafikiHub will not accept fees for work on behalf of any Member; all payments for work must be arranged between the worker and the hirer, or their official representative.` },
  { type: 'heading', level: 6, text: `EQUAL OPPORTUNITIES` },
  { type: 'p', text: `Please note that RafikiHub is not involved in compiling the job adverts which appear on The RafikiHub Link. RafikiHub is committed to equal opportunities for all performers, irrespective of sex, age, race, disability, religion, sexual orientation, marital status or any other criteria not related to skills or abilities. Where sex, age, height and/or appearance has been specified on an advert, the casting director has confirmed that such characteristics are a genuine occupational requirement of the role.` },
  { type: 'heading', level: 6, text: `NATIONAL MINIMUM WAGE` },
  { type: 'p', text: `RafikiHub strongly believes that all commercial productions should pay performers the National Minimum Wage or above. However, we cannot take responsibility for the payment offered by any company, organisation or individual using our casting services. Please see the Kenya Film Commission/Kenya Actors Guild current guidance for full information about the legal framework which covers low pay and no pay work in the entertainment industry, to ensure that you understand rights and entitlements.` },
  { type: 'heading', level: 6, text: `EMPLOYING CHILDREN AND YOUNG PERFORMERS` },
  { type: 'p', text: `You are reminded that it is illegal for children under the age of 16 to work without formal licensing in place, otherwise they are not insured or protected. Please ensure that Young Performers are always licensed.` },
  { type: 'heading', level: 4, text: `GENERAL TERMS` },
  { type: 'heading', level: 6, text: `Indemnity` },
  { type: 'p', text: `If you breach these terms we may suffer loss. You agree to indemnify us against any and all claims, actions, suits or proceedings, as well as any and all losses, liabilities, damages, costs and expenses (including reasonable legal fees) arising out of any non-compliance by you with these terms and conditions.` },
  { type: 'heading', level: 6, text: `Entire Agreement` },
  { type: 'p', text: `These terms and conditions (as amended from time to time) together with any document expressly referred to in them comprise the entire agreement between you and us.` },
  { type: 'heading', level: 6, text: `Severability` },
  { type: 'p', text: `Each provision of these terms and conditions shall be construed separately, applying and surviving even if for any reason one or other provisions is held to be inapplicable or unenforceable in any circumstances.` },
  { type: 'heading', level: 6, text: `No Waiver` },
  { type: 'p', text: `No waiver by us shall be construed as a waiver of any preceding or succeeding breach of any provision.` },
  { type: 'heading', level: 6, text: `Kenyan Law` },
  { type: 'p', text: `These terms and conditions shall be governed by Kenyan law and you submit to the exclusive jurisdiction of the Kenyan Courts.` },
  { type: 'p', text: `RafikiHub is committed to using clear and understandable terminology in all of our documents and correspondence, however if anything within this document is unclear then please contact us.` },
  { type: 'heading', level: 2, text: `Sales & Payment Service Terms` },
  { type: 'p', text: `This Site and related Services are provided by RafikiHub whose trading name is Sio Bahati Holdings Ltd & trading address is in the Republic of Kenya. Registered in the Republic of Kenya, Company Number PVT-ZQUAMRQ.` },
  { type: 'p', text: `For details of how to contact us click here.` },
  { type: 'p', text: `By agreeing to these terms and conditions, you are entering into contract with RafikiHub and agreeing to the lawful use of your personal data as necessary for the performance of your contract with us.` },
  { type: 'p', text: `These terms and conditions set out the conditions relating to purchases available via the RafikiHub Site, including RafikiHub Member Services and RafikiHub Casting Services, and are incorporated into and form part of those respective terms.` },
  { type: 'p', text: `If you do not agree with any part of these terms and conditions do not continue with your order. If you have any questions please contact info@rafikihub.com` },
  { type: 'p', text: `Nothing in these terms is intended to limit any rights you have under the applicable area of consumer, or local, law.` },
  { type: 'p', text: `You should print and keep a copy of the relevant service terms, Site Terms and these Sales and Payment terms for your records as at the date of joining or renewing.` },
  { type: 'p', text: `Please also read our Privacy Policy. Please also read our Website Terms and Conditions which are applicable for certain purchases.` },
  { type: 'heading', level: 4, text: `Payment` },
  { type: 'p', text: `The placing of an order amounts to an offer to join, subscribe or purchase as appropriate. All offers are subject to our acceptance.` },
  { type: 'p', text: `RafikiHub must normally receive payment of the whole of the price for the goods or services that you order before your order can be accepted. It is not our policy to offer credit accounts for payments. Please do not be offended if we refuse your request.` },
  { type: 'p', text: `If you are a brand new RafikiHub Member, please ensure you have read and understand the terms around your one-off cooling off period which can be found in the Member Services Terms. For certain membership groups, if paying by card, your card may be pre-authorised, which creates a hold on your card until payment is taken or the transaction is cancelled.` },
  { type: 'p', text: `You will be charged in the currency as indicated at the checkout phase which, if not the country of your bank account, will be converted by your bank into the currency of your bank account, when processed. We are not responsible for any additional fees your own bank may charge.` },
  { type: 'p', text: `We accept Visa, MasterCard, Maestro (Switch), Debit cards, M-Pesa, AirTel Money. We do not accept American Express or Diners Card.` },
  { type: 'p', text: `Should we need to refund you for any reason, we will refund to the card or other payment method on which the order was placed.` },
  { type: 'p', text: `Once you have submitted your payment details your order will automatically proceed, and we will not be able to stop the payment going through at this stage. Should you have any concerns regarding a payment that has been sent through for processing please contact us at info@rafikihub.com` },
  { type: 'p', text: `Should you receive an invoice from us, or receive a service from us without paying in advance or on the day, the payment terms will be stated on the invoice, if applicable, or due immediately. We reserve the right not to proceed with additional services, even if a deposit or full payment has been made, until all due payments have been received.` },
  { type: 'p', text: `In the event of late payment we may charge interest on a daily basis from the date payment was due in accordance with the Late Payment of Commercial Debts (Interest) Act 1998. We may also seek to recover your Debt Collection Agency costs.` },
  { type: 'heading', level: 4, text: `VAT Exemption` },
  { type: 'p', text: `If you ask for your invoice to be zero-rated for Kenyan VAT, you will be required to provide a tax exemption certificate. Please note that we are unable to zero-rate room hire, no matter where you are based. If it is subsequently found that your invoice should not have been tax exempt, we will send you an invoice for the underpaid VAT, which you will be obliged to pay.` },
  { type: 'heading', level: 4, text: `Liability` },
  { type: 'p', text: `If the service you have ordered is no longer available RafikiHub will notify you as soon as possible, and any sum debited by us from your credit or debit card, will be re-credited to your account. RafikiHub will not be obliged to offer any other replacement or compensation in the event of this happening.` },
  { type: 'p', text: `RafikiHub is entitled to withdraw from any purchase agreement in the case of obvious errors or inaccuracies regarding the services appearing on our Site.` },
  { type: 'p', text: `The above conditions apply only to purchases made via our own sites. Purchases made via third party sites, are subject to any Terms & Conditions set out by those third parties` },
  { type: 'heading', level: 4, text: `Right to refuse orders` },
  { type: 'p', text: `We reserve the right to refund your money and deny access to the Services:` },
  { type: 'list', items: [`If we are unable to verify your relevant credentials.`, `If we find orders have been made with false information, or where we find that there has been any fraudulent or criminal activity associated with the person or company concerned.`, `In the event of obvious inaccuracies in prices, except that we may fulfil your order at the correct price.`, `If we are unable to obtain payment authorisation from the issuer of your payment card.`] },
  { type: 'heading', level: 4, text: `Website Security` },
  { type: 'p', text: `We take all reasonable precautions to the keep customer website transactions secure. Secure card processing is carried out by trusted third party payment providers on our behalf. However, RafikiHub cannot be held liable for any losses caused as a result of unauthorised access to the information provided by you. We also have strict security procedures regarding the storage and disclosure of information (see our Privacy Policy).` },
  { type: 'p', text: `The security of information and payments transmitted via the internet cannot be guaranteed. Any losses incurred or sustained by users who transmit information by means of email or other internet link shall be borne solely and exclusively by such user and in no event shall any such losses in whole or part be borne by RafikiHub.` },
  { type: 'p', text: `Security advice note: We recommend that when making an online transaction you do not use a public or shared computer or a device such as a laptop or mobile phone while you are using public wireless networks. Make sure that nobody can see your confidential details whilst you are typing, logout and close your browser when you have finished. The computer you use to attach to our payments system should be secure, and include the latest operating system, software and anti-virus updates.` },
  { type: 'heading', level: 4, text: `Discounts and Offers` },
  { type: 'p', text: `All offers and discounts provided by RafikiHub are subject to availability and supplied at our discretion and as available at that time. Discounts and offers are not retrospective. For certain ongoing discounts, such as those on membership fees, supporting evidence may be required at intervals. RafikiHub reserves the right to amend offers and discounts at any time.` },
  { type: 'heading', level: 4, text: `General Terms` },
  { type: 'heading', level: 6, text: `Indemnity` },
  { type: 'p', text: `If you breach these terms we may suffer loss. You agree to indemnify us against any and all claims, actions, suits or proceedings, as well as any and all losses, liabilities, damages, costs and expenses (including reasonable legal fees) arising out of any non-compliance by you with these terms and conditions.` },
  { type: 'heading', level: 6, text: `Entire Agreement` },
  { type: 'p', text: `These terms and conditions (as amended from time to time) together with any document expressly referred to in them comprise the entire agreement between you and us.` },
  { type: 'heading', level: 6, text: `Severability` },
  { type: 'p', text: `Each provision of these terms and conditions shall be construed separately, applying and surviving even if for any reason one or other provisions is held to be inapplicable or unenforceable in any circumstances.` },
  { type: 'heading', level: 6, text: `No Waiver` },
  { type: 'p', text: `No waiver by us shall be construed as a waiver of any preceding or succeeding breach of any provision.` },
  { type: 'heading', level: 6, text: `Kenyan Law` },
  { type: 'p', text: `These terms and conditions shall be governed by Kenyan law and you submit to the exclusive jurisdiction of the Kenyan Courts.` },
  { type: 'p', text: `RafikiHub is committed to using clear and understandable terminology in all of our documents and correspondence, however if anything within this document is unclear then please contact us.` },
  { type: 'heading', level: 2, text: `Casting Services Terms` },
  { type: 'p', text: `This Site and related Services are provided by RafikiHub whose trading name is Sio Bahati Holdings Ltd & trading address is in the Republic of Kenya. Registered in the Republic of Kenya, Company Number PVT-ZQUAMRQ.` },
  { type: 'p', text: `For details of how to contact us click here` },
  { type: 'heading', level: 4, text: `Use of RafikiHub` },
  { type: 'p', text: `By agreeing to these terms and conditions, you are entering into contract with RafikiHub and agreeing to the lawful use of your personal data as necessary for the performance of your contract with us.` },
  { type: 'p', text: `Before agreeing to these terms and conditions please ensure you have read the Site Terms relating to our terms of use for our Site, as these form part of your Subscription Conditions. In the event of any conflict, these service terms will take precedence.` },
  { type: 'p', text: `You should print and keep a copy of these terms, the Site terms and the Sales and Payment terms for your records as at the date of joining or renewing.` },
  { type: 'p', text: `Please also read our Privacy Policy` },
  { type: 'heading', level: 4, text: `Definitions` },
  { type: 'p', text: `- "Agent" means an authorised agent of a performer, who is a Member of RafikiHub. - "RafikiHub Casting Services" and "Services" means the services made available to Casting Professionals as detailed below and on the Site. - "RafikiHub Casting Professional/RafikiHub Casting Team Owner" means a casting professional who has signed up with RafikiHub as a recipient of the Casting Services. - "Content" means the information and other material or applications available within the Site or relevant Services. - "RafikiHub Member" means a performer who has signed up with RafikiHub as a member of its database and recipient of the Member Services. - "Sales and Payment Terms" means the further specific terms relating to the processing of any payments. - "Site" means the sites located at rafikihub.com - "We/Us" means RafikiHub. - "You" means the user of the Site(s) or the Content or otherwise the RafikiHub Casting Professional. These terms and conditions set out the conditions relating to joining RafikiHub as a RafikiHub Casting Professional and receiving RafikiHub Casting Services.` },
  { type: 'heading', level: 4, text: `RafikiHub Casting Services` },
  { type: 'p', text: `RafikiHub provides casting professionals with a range of tools and services to assist the casting process, including access to the RafikiHub Database of Professional Performers and Industry Specialists. The Services are summarised below with further information available on the Site as indicated.` },
  { type: 'heading', level: 4, text: `RafikiHub Interactive` },
  { type: 'p', text: `RafikiHub Interactive will be part of the services you will have access to and allows you to search our database of performers including actors, actresses, Young Performers, creative department and other industry professionals.` },
  { type: 'heading', level: 4, text: `The RafikiHub Link` },
  { type: 'p', text: `Subject to the level of your subscription you may also be eligible to send casting breakdowns to agents and performers across our casting service, The RafikiHub Link. As part of this service you may also be eligible to send casting breakdowns via our RafikiHub network partners in other territories, and in this instance, your contact details will be made available to the partner service you have selected so that they can contact you regarding circulating your casting information more widely.` },
  { type: 'heading', level: 4, text: `RafikiHub Casting` },
  { type: 'p', text: `RafikiHub Casting is an end-to-end casting service for the professional casting industry, providing tools for streamlining the casting process. Please note that you are responsible for ensuring you have the appropriate permissions from RafikiHub Members (performers), non-member performers and other partners or collaborators ("RafikiHub Casting Invited Users") that you invite to participate in your use of the RafikiHub Casting tools. You are responsible for ensuring that all content, information and data used or stored via the tools complies with all laws, regulations, is copyright cleared and does not infringe any third party rights, and otherwise complies with all relevant RafikiHub terms and conditions.` },
  { type: 'heading', level: 4, text: `RafikiHub Casting Subscriber Criteria` },
  { type: 'p', text: `To be a RafikiHub Casting Subscriber you must be a stage, television, film, radio or advertising professional or similar. Continued use of RafikiHub Casting Services in general is dependent on the professional validity of casting information being sent across the system. We reserve the right to end access to RafikiHub Casting Services at any time, and without warning, should we believe misuse has taken place, or if we receive complaints related to inappropriate information being sent out to Agents and RafikiHub Members or other performers, Casting team members and/or invitees (this could include any material that does not meet our professional standards, or is defamatory, offensive, obscene or of a threatening nature). We also reserve the right to terminate access where legitimate concerns are raised by professional industry organisations, or where our staff or other persons are subject to abusive, offensive or threatening behaviour.` },
  { type: 'heading', level: 4, text: `Single user Restriction` },
  { type: 'p', text: `If you are a RafikiHub Casting Subscriber, you must not share your user details with anyone else. RafikiHub Casting Subscriptions/access credentials are for one person's use. Sharing a password may mean someone accessing the RafikiHub services who is not eligible to do so. Password sharing is a breach of our terms and conditions.` },
  { type: 'heading', level: 4, text: `Content` },
  { type: 'p', text: `It is the responsibility of the RafikiHub Casting Subscriber to ensure that they have full copyright clearance for materials and content featured as part of a casting breakdown. This must be cleared for all uses set out in these terms and conditions. RafikiHub Casting Subscribers listing details of forthcoming productions on the RafikiHub Casting Services are responsible for ensuring that they have consent from their own hirer (Production Company, Director etc.) to do so, so that confidential production information is not released. You confirm that all information provided by you is truthful, honest and accurate. You must not upload material that is unlawful, defamatory, abusive, obscene, discriminatory or otherwise inappropriate. RafikiHub does not offer its users the ability to download or otherwise recover media files in their original quality or format. RafikiHub therefore strongly recommends that RafikiHub Casting Subscribers retain their original media files. Furthermore RafikiHub cannot be held responsible for loss or corruption of data, including accidental or intentional deletion by any party. PLEASE NOTE: whilst we prohibit Scraping or Extraction of the Site Content, we cannot guarantee that this activity will not occur without our permission. In any event, in order to facilitate Members, Agents and Casting Professionals with their workflow management processes or other activity, RafikiHub may from time to time provide or authorise the use of certain third party software or applications to facilitate additional off Site access to the materials and Content. Such third party packages or systems are strictly subject to the written approval of RafikiHub. A list of currently authorised third party packages or systems is available to RafikiHub Casting Professionals/RafikiHub Agents/RafikiHub Members by contacting RafikiHub. You acknowledge that your Content may be copied, moved and used in this way. Please note however that RafikiHub does not endorse and is not responsible for any such third party packages or systems, and RafikiHub will not be liable for any loss of information, materials, data or otherwise that may occur due to the use of your materials within them. RafikiHub reserves the right to suspend or withdraw services from those who violate our terms and conditions and to remove material which it considers to be in breach of these terms and conditions. RafikiHub reserves the right not to use or make available any material which it deems inappropriate.` },
  { type: 'heading', level: 4, text: `Site Content reuse/restrictions` },
  { type: 'p', text: `You may use RafikiHub for professional casting purposes only. You may not promote other casting services within RafikiHub’s Site or tools, nor require or suggest that submissions may be received by any means other than RafikiHub. The Content and/or information sent or made available via The RafikiHub Link/RafikiHub Casting is the confidential information and copyright of your employer (hirer) or yourself. In using RafikiHub, you agree not to forward or copy any part of this information or recordings of performances and auditions outside the casting system without consent from your hirer where required and/or the consent of the RafikiHub Member (performer) concerned. All production and performer information (RafikiHub Member and other performer profiles/comments) shared with you should be treated as strictly private and confidential and details should not be released to any other parties without their consent. RafikiHub Casting Professionals will be liable where they cause damage (including financial loss) to any other party, including an employer, by releasing confidential information into the public domain. RafikiHub or its licensees retain copyright and other intellectual property rights in its database and in the contents of its database. You may print off results of your searches with photographs but you must include any and all copyright notices and credits that appear on the screen display of the website page. Any breach of these terms could cause inconvenience and loss to various parties, and loss to RafikiHub. RafikiHub reserves the right to terminate your access to The RafikiHub Link without notice in the event of a breach. It also reserves the right to withdraw or withhold service where it considers this to be commercially desirable or for any other reason it deems appropriate.` },
  { type: 'heading', level: 6, text: `Other responsibilities` },
  { type: 'heading', level: 6, text: `EQUAL OPPORTUNITIES` },
  { type: 'p', text: `RafikiHub is committed to equal opportunities for all performers, irrespective of age, gender, colour, race/ethic national origins, or disability. Unless the role your casting has very specific requirements in one of these categories, please always make your casting search as inclusive as possible. It is your responsibility to ensure that you are acquainted with your legislative responsibilities in relation to Equal Opportunities.` },
  { type: 'heading', level: 6, text: `NATIONAL MINIMUM WAGE` },
  { type: 'p', text: `If you are offering unpaid or low-paid work, please ensure that you fully understand your obligations regarding the National Minimum Wage. You can seek guidance on the minimum wage for the industry from the Kenya Film Commission/Kenya Actors Guild.` },
  { type: 'heading', level: 6, text: `EMPLOYING CHILDREN AND YOUNG PERFORMERS` },
  { type: 'p', text: `You are reminded that it is illegal for Young Performers under the age of 16 to work without formal licensing in place, otherwise they are not insured or protected. Please ensure that child performers are always licensed.` },
  { type: 'heading', level: 6, text: `DATA PROTECTION` },
  { type: 'p', text: `You are reminded that in processing data relating to hirers, agents and performers you must comply at all times with current Data Protection legislation.` },
  { type: 'heading', level: 4, text: `RafikiHub Casting Subscription Process` },
  { type: 'p', text: `Casting Subscriptions can be purchased via our website. Please see our Sales & Payment Terms for more information relating to the processing of your payments.` },
  { type: 'p', text: `Once you have completed your information you will proceed to a checkout screen. After you submit your RafikiHub Casting Subscription application our online payment provider will process your payment automatically. This does not represent acceptance of your order by us. Your professional credentials will subsequently be verified, and your first casting draft reviewed if you are using the RafikiHub Link, and we reserve the right to refuse your order and refund your purchase costs at any stage. We additionally reserve the right to refer to other professional bodies, such as the Kenya Actors Guild & Kenya Film Commission, if we have specific concerns regarding company background or information supplied (such as terms of employment or similar).` },
  { type: 'heading', level: 4, text: `RafikiHub Casting Subscription Periods and benefits/access` },
  { type: 'p', text: `Our Casting Service subscriptions have different duration periods. Therefore you should check the type of access you are purchasing, associated costs and also the period of access before submitting your order. The price for your subscription model will be confirmed at checkout before your order goes through.` },
  { type: 'heading', level: 4, text: `Subscription Notification` },
  { type: 'p', text: `We attempt to process all Casting Subscription orders within forty-eight hours of receipt during office hours (our office hours: Monday - Friday 09.00am- 5.00pm). However, this may not always be possible, although all orders would normally be processed within 48-hours on a normal working day.` },
  { type: 'heading', level: 4, text: `Cancellations & Refunds` },
  { type: 'p', text: `You may not cancel this order once payment has been taken and you have been given full access to RafikiHub data. However, we will consider cancellations where access to our data has not yet been provided.` },
  { type: 'heading', level: 4, text: `Disclaimers & Liability` },
  { type: 'p', text: `RafikiHub’s database contains information about RafikiHub Members (performers) which is provided by the performing artists themselves, or their Agents. Notwithstanding that appropriate steps have been taken to ensure that the information is accurate, RafikiHub (and those organisations on whose behalf we publish) cannot be held responsible for any errors or omissions, and cannot accept liability for reliance placed on the contents and/or any omissions which may occur. Those employing RafikiHub Members (performers) or specialists must make their own enquiries of the RafikiHub Member (performer) / specialist to satisfy themselves that he/she is competent to perform the skills required. Due to the inherent nature of the internet, and other technology systems we use, errors, interruptions and delays may occur in the Service at any time. Accordingly, the Site and Services are provided without any warranties of any kind and we do not accept any liability arising from any inaccuracy or omission in the information or interruption in availability. To the maximum extent permitted by applicable law, we exclude all liability for any indirect, special, consequential or punitive damages, or any loss of income, profits, goodwill, data or contracts arising from or connected in any way to your use of the Services or the Site, whether in tort (including without limitation negligence), contract or otherwise, even if advised of the possibility of such damages. To the extent there is any liability on us, this is limited at a maximum amount per claim and in aggregate to the annual amount paid by you for the relevant Service. This Section does not in any way limit our liability for death or personal injury caused by our negligence; for fraud or fraudulent misrepresentation; or for any implied terms or other matter for which it would be illegal for us to exclude, or attempt to exclude, our liability.` },
  { type: 'heading', level: 4, text: `Website and Software Application Security` },
  { type: 'p', text: `We take all reasonable precautions to keep interactions on our Site and Application(s) secure. We also have strict security procedures regarding the storage and disclosure of information. However, RafikiHub cannot be held liable for any losses caused as a result of unauthorised access to the information provided by you. The security of information transmitted via the internet cannot be guaranteed. Any losses incurred or sustained by users who transmit information by means of syncing data between the Site and Application, sharing data via the RafikiHub Casting service, email or other internet link, or capture/store information by means of the Application or other recording or storage facilities shall be borne solely and exclusively by such user and in no event shall any such losses in whole or part be borne by RafikiHub.` },
  { type: 'heading', level: 4, text: `General Terms` },
  { type: 'heading', level: 6, text: `Indemnity` },
  { type: 'p', text: `If you breach these terms we may suffer loss. You agree to indemnify us against any and all claims, actions, suits or proceedings, as well as any and all losses, liabilities, damages, costs and expenses (including reasonable legal fees) arising out of any non-compliance by you with these terms and conditions.` },
  { type: 'heading', level: 6, text: `Entire Agreement` },
  { type: 'p', text: `These terms and conditions (as amended from time to time) together with any document expressly referred to in them comprise the entire agreement between you and us.` },
  { type: 'heading', level: 6, text: `Severability` },
  { type: 'p', text: `Each provision of these terms and conditions shall be construed separately, applying and surviving even if for any reason one or other provisions is held to be inapplicable or unenforceable in any circumstances.` },
  { type: 'heading', level: 6, text: `No Waiver` },
  { type: 'p', text: `No waiver by us shall be construed as a waiver of any preceding or succeeding breach of any provision.` },
  { type: 'heading', level: 6, text: `Kenyan Law` },
  { type: 'p', text: `These terms and conditions shall be governed by Kenyan law and you submit to the exclusive jurisdiction of the Kenyan Courts.` },
  { type: 'p', text: `RafikiHub is committed to using clear and understandable terminology in all of our documents and correspondence, however if anything within this document is unclear then please contact us.` },
]
